<template><div class="page"><div class="page-head"><div><span>MODEL CENTER / REGISTRY</span><h2>预测模型管理</h2><p>统一查看模型版本、训练数据、评估指标和运行状态。</p></div><el-button type="primary" :disabled="!selected" :loading="running" @click="run">运行选中模型</el-button></div><div class="overview"><el-card shadow="never"><small>已登记模型</small><strong>{{ models.length }}</strong><span>3 个业务方向</span></el-card><el-card shadow="never"><small>在线模型</small><strong class="success">{{ onlineCount }}</strong><span>可直接运行</span></el-card><el-card shadow="never"><small>最近运行</small><strong>{{ lastRun || '—' }}</strong><span>演示数据集</span></el-card></div><div class="layout"><el-card shadow="never" class="model-card"><template #header><div class="card-title"><b>模型目录</b><el-tag type="success">运行环境正常</el-tag></div></template><div v-for="model in models" :key="model.id" :class="['model-row',{selected:model.id===selected?.id}]" @click="selected=model"><div class="model-icon">{{ model.short }}</div><div class="model-main"><b>{{ model.name }}</b><span>{{ model.type }} · {{ model.version }}</span><small>{{ model.description }}</small></div><el-tag type="success" effect="plain">在线</el-tag></div></el-card><el-card shadow="never" class="detail-card"><template #header><b>模型详情</b></template><template v-if="selected"><div class="detail-head"><div><h3>{{ selected.name }}</h3><p>{{ selected.description }}</p></div><el-tag type="success">已启用</el-tag></div><el-descriptions :column="2" border><el-descriptions-item label="模型类型">{{ selected.type }}</el-descriptions-item><el-descriptions-item label="版本">{{ selected.version }}</el-descriptions-item><el-descriptions-item label="输入数据">{{ selected.input }}</el-descriptions-item><el-descriptions-item label="更新时间">{{ selected.updated }}</el-descriptions-item><el-descriptions-item label="验证集样本">{{ selected.samples }}</el-descriptions-item><el-descriptions-item label="验证评分">{{ selected.score }}</el-descriptions-item></el-descriptions><div class="metric-title">评估指标</div><div class="metrics"><div><span>准确率</span><b>{{ selected.accuracy }}%</b><el-progress :percentage="selected.accuracy" :show-text="false"/></div><div><span>稳定性</span><b>{{ selected.stability }}%</b><el-progress :percentage="selected.stability" :show-text="false" status="success"/></div></div></template></el-card></div><el-card v-if="result" shadow="never" class="run-result"><template #header><b>最近一次运行结果</b></template><el-alert title="模型运行完成" type="success" show-icon :closable="false"/><el-descriptions :column="4" border><el-descriptions-item label="模型">{{ result.model }}</el-descriptions-item><el-descriptions-item label="样本数">{{ result.samples }}</el-descriptions-item><el-descriptions-item label="评分">{{ result.score }}</el-descriptions-item><el-descriptions-item label="结论">{{ result.conclusion }}</el-descriptions-item></el-descriptions></el-card></div></template>
<script setup>import{ref,computed}from'vue';import{ElMessage}from'element-plus';const models=ref([{id:1,short:'HI',name:'健康指数趋势模型',type:'健康评估',version:'v2.1.0',input:'HI / 遥测窗口',description:'根据多通道健康指数识别退化趋势。',updated:'2026-09-10',samples:480,score:'0.92',accuracy:92,stability:89},{id:2,short:'RUL',name:'基础 RUL 预测模型',type:'寿命预测',version:'v1.4.2',input:'健康指数序列',description:'输出剩余寿命区间和退化阶段。',updated:'2026-09-08',samples:320,score:'0.87',accuracy:87,stability:84},{id:3,short:'DIA',name:'Hier14 故障诊断模型',type:'故障诊断',version:'v1.2.0',input:'CSV 遥测窗口',description:'结合规则与特征证据定位故障模式。',updated:'2026-09-06',samples:620,score:'0.95',accuracy:95,stability:93}]);const selected=ref(models.value[0]),running=ref(false),result=ref(null),lastRun=ref('今天'),onlineCount=computed(()=>models.value.length);async function run(){running.value=true;await new Promise(r=>setTimeout(r,500));result.value={model:selected.value.name,samples:selected.value.samples,score:selected.value.score,conclusion:'输出稳定，结果已写入演示记录'};lastRun.value='刚刚';running.value=false;ElMessage.success('模型运行完成')}</script>
<style scoped>.page{max-width:1250px}.page-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.page-head span{font-size:12px;color:#1677ff;letter-spacing:1px}.page-head h2{margin:8px 0}.page-head p{margin:0;color:#718198}.overview{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:16px}.overview strong{display:block;font-size:28px;margin:5px 0}.overview small,.overview span{color:#718198;font-size:13px}.success{color:#19a974}.layout{display:grid;grid-template-columns:420px 1fr;gap:16px}.card-title,.detail-head{display:flex;justify-content:space-between;align-items:center}.model-row{display:flex;align-items:center;gap:12px;padding:14px 10px;border:1px solid transparent;border-bottom-color:#edf1f5;cursor:pointer}.model-row.selected{background:#eef6ff;border-color:#9bc7f5}.model-icon{display:grid;place-items:center;width:40px;height:40px;border-radius:8px;background:#e8f2ff;color:#1677ff;font-weight:700;font-size:12px}.model-main{display:flex;flex:1;flex-direction:column;gap:3px}.model-main span,.model-main small,.detail-head p{color:#718198;font-size:12px}.detail-head h3{margin:0 0 6px}.metric-title{font-weight:600;margin:22px 0 12px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:22px}.metrics span{display:block;color:#718198;font-size:13px}.metrics b{display:block;margin:5px 0}.run-result{margin-top:16px}.el-alert{margin-bottom:16px}@media(max-width:800px){.page-head{display:block}.page-head .el-button{margin-top:14px}.overview,.layout{grid-template-columns:1fr}.metrics{grid-template-columns:1fr}}</style>
